void update_jacobian_reaction_0(std::vector<Triplet_>& jacobian_triplets,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_0,
                                               const double& dequilibrium_constant_0_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_0 = call_forward_reaction_0(temperature, log_temperature);
        double dforward_reaction_0_dtemperature = dcall_forward_reaction_0_dtemperature(temperature,log_temperature);

        dforward_reaction_0_dtemperature += dcall_forward_reaction_0_dlog_temperature(temperature,log_temperature) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_0 = multiply(species[0] * species[3], forward_reaction_0) - multiply(species[2] * species[4], divide(forward_reaction_0, equilibrium_constant_0));
        

        //drate_of_progress_dspecies[0] = {double(0)};
        drate_of_progress_dspecies = multiply(species[3], forward_reaction_0); // [0][0] +
        jacobian_triplets.push_back(Triplet_(1, 1, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(4, 1, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(3, 1, drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(5, 1, drate_of_progress_dspecies));
        drate_of_progress_dspecies = multiply(species[0], forward_reaction_0); // [0][3] +
        jacobian_triplets.push_back(Triplet_(1, 4, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(4, 4, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(3, 4, drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(5, 4, drate_of_progress_dspecies));
        drate_of_progress_dspecies = -multiply(species[4], divide(forward_reaction_0, equilibrium_constant_0));
        jacobian_triplets.push_back(Triplet_(1, 3, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(4, 3, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(3, 3, drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(5, 3, drate_of_progress_dspecies));
        drate_of_progress_dspecies = -multiply(species[2], divide(forward_reaction_0, equilibrium_constant_0));
        jacobian_triplets.push_back(Triplet_(1, 5, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(4, 5, -drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(3, 5, drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(5, 5, drate_of_progress_dspecies));
}


