        jacobian_triplets.push_back(Triplet_(3, 3, drate_of_progress_dspecies));
        drate_of_progress_dspecies = -multiply(species[2], divide(forward_reaction_4, equilibrium_constant_4));
        jacobian_triplets.push_back(Triplet_(5, 6, -2.0*drate_of_progress_dspecies));
        jacobian_triplets.push_back(Triplet_(6, 6, drate_of_progress_dspecies));
